	private sealed class AnimationEntry
	{
		public string Key { get; }

		public string ClipName { get; }

		public bool Clamp { get; }

		public double? ProgressDurationSeconds { get; }

		public AnimationEntry(string key, string clipName, bool clamp = false, double? progressDurationSeconds = null)
		{
			Key = key;
			ClipName = clipName;
			Clamp = clamp;
			ProgressDurationSeconds = progressDurationSeconds;
		}

		public string BuildLua(string targetId)
		{
			string text = (Clamp ? "\n        playbackMode = 0," : string.Empty);
			return "    " + Key + " = {\n        clipName = \"" + ClipName + "\",\n        sanAnimationPath = \"Units/" + targetId + "/LOD0/" + targetId + ".sananimation\"," + text + "\n    },";
		}
	}

	private sealed class WeaponRig
	{
		public string YawBone { get; }

		public string PitchBone { get; }

		public string AimBone { get; }

		public IReadOnlyList<string[]> MuzzleGroups { get; }

		public IReadOnlyList<string> RequiredAliases { get; }

		public WeaponRig(string yawBone, string pitchBone, string aimBone, IReadOnlyList<string[]> muzzleGroups, IReadOnlyList<string>? requiredAliases = null, bool sourceParallelProjectiles = false)
		{
			if (muzzleGroups.Count == 0 || muzzleGroups.Any((string[] group) => group.Length == 0))
			{
				throw new ArgumentException("A weapon rig requires non-empty muzzle groups.", "muzzleGroups");
			}
			string[] array = muzzleGroups.SelectMany((string[] group) => group).ToArray();
			bool flag = array.Distinct(StringComparer.Ordinal).Count() != array.Length;
			if (flag && !sourceParallelProjectiles)
			{
				throw new ArgumentException("A weapon rig may repeat physical endpoints only for a source ProjectilesPerOnFire contract.", "muzzleGroups");
			}
			if (sourceParallelProjectiles && !flag)
			{
				throw new ArgumentException("A source ProjectilesPerOnFire contract requires at least one repeated physical endpoint.", "muzzleGroups");
			}
			YawBone = yawBone;
			PitchBone = pitchBone;
			AimBone = aimBone;
			MuzzleGroups = muzzleGroups;
			RequiredAliases = requiredAliases ?? Array.Empty<string>();
		}

		public string BuildLua(string templateId)
		{
			string text = string.Join(",\n", MuzzleGroups.Select((string[] group) => "{ muzzles = { " + string.Join(", ", group.Select(Quote)) + " } }"));
			string text2 = string.Join("\n", from line in text.Split(new char[1] { '\n' }, StringSplitOptions.None)
				select "        " + line);
			string text3 = ((RequiredAliases.Count == 0) ? "none" : string.Join(", ", RequiredAliases));
			return "-- Required identity aliases supplied by the model converter: " + text3 + "\nlocal combatWeapon = UnitTemplate.weapons and UnitTemplate.weapons[1]\nif not combatWeapon\n    or not combatWeapon.aimControllers\n    or not combatWeapon.aimControllers[1]\nthen\n    error(\"" + templateId + " requires its source weapon/aim-controller contract\")\nend\n\nlocal aimController = combatWeapon.aimControllers[1]\naimController.aimBone = \"" + AimBone + "\"\naimController.yawBone = \"" + YawBone + "\"\naimController.pitchBone = \"" + PitchBone + "\"\ncombatWeapon.muzzleGroups = {\n" + text2 + "\n}";
		}

		private static string Quote(string value)
		{
			return "\"" + value.Replace("\\", "\\\\").Replace("\"", "\\\"") + "\"";
		}
	}

	private sealed class PatchSpec
	{
		public string TargetId { get; }

		public string Description { get; }

		public string RelativePath { get; }

		public string Appendix { get; }

		public WeaponRig? Weapon { get; }

		public bool IsVirtual { get; }

		public string? VirtualSource { get; }

		public PatchSpec(string targetId, string description, string appendix, WeaponRig? weapon = null)
			: this(targetId, "LJ/lua/common/units/unitsTemplates/" + targetId + "/" + targetId + ".santp", description, appendix, weapon)
		{
		}

		private PatchSpec(string targetId, string relativePath, string description, string appendix, WeaponRig? weapon, bool isVirtual = false, string? virtualSource = null)
		{
			TargetId = targetId;
			Description = description;
			RelativePath = relativePath;
			if (string.Equals(relativePath, "LJ/lua/host/units/unitsClasses/unitsDefaultEDA.lua", StringComparison.Ordinal))
			{
				appendix = RepairFaT1PowerCompletionRace(appendix);
			}
			Appendix = "\n\n-- Supreme Commander Overhaul EDA UEF Land/Power Cache Patcher 3.0.0\n" + appendix.TrimStart('\r', '\n');
			Weapon = weapon;
			IsVirtual = isVirtual;
			VirtualSource = virtualSource;
			if (weapon != null && (Appendix.IndexOf("combatWeapon.aimControllers", StringComparison.Ordinal) < 0 || Appendix.IndexOf("combatWeapon.muzzleGroups", StringComparison.Ordinal) < 0))
			{
				throw new InvalidOperationException(targetId + " is missing its weapon-rig override.");
			}
		}

		public static PatchSpec ForResource(string relativePath, string description, string appendix)
		{
			return new PatchSpec(relativePath, relativePath, description, appendix, null);
		}

		public static PatchSpec ForVirtualResource(string relativePath, string description, string source)
		{
			string virtualSource = ((source.IndexOf("-- Supreme Commander Overhaul EDA UEF Land/Power Cache Patcher 3.0.0", StringComparison.Ordinal) >= 0) ? source : (source.TrimEnd(Array.Empty<char>()) + "\n\n-- Supreme Commander Overhaul EDA UEF Land/Power Cache Patcher 3.0.0\n"));
			return new PatchSpec(relativePath, relativePath, description, string.Empty, null, isVirtual: true, virtualSource);
		}
	}

	private sealed class CachedResource
	{
		public PatchSpec Spec { get; }

		public string Path { get; }

		public object? Stock { get; }

		public object? Replacement { get; set; }

		public bool ReplacementWasAssigned { get; set; }

		public CachedResource(PatchSpec spec, string path, object? stock)
		{
			Spec = spec;
			Path = path;
			Stock = stock;
		}
	}

