	private static string RepairFaT1PowerCompletionRace(string appendix)
	{
		if (appendix.IndexOf("function EDAImportedAnimatedEnergyGenerator:SCO_BeginFaT1PowerOpening(generation)\n    if self.dead or self.tpId ~= \"ues1611\" then\n        return\n    end\n", StringComparison.Ordinal) < 0 || appendix.IndexOf("    local generation = self.scoFaT1PowerLifecycleGeneration\n    self:SetRotatorsEnabled(false)\n", StringComparison.Ordinal) < 0 || appendix.IndexOf("function EDAImportedAnimatedEnergyGenerator:OnStopBeingBuilt()\n    EDAEnergyGenerator.OnStopBeingBuilt(self)\n    if self.tpId == \"ues1611\" then\n        self.scoFaT1PowerLifecycleGeneration = (self.scoFaT1PowerLifecycleGeneration or 0) + 1\n        self:SCO_BeginFaT1PowerOpening(self.scoFaT1PowerLifecycleGeneration)\n    end\nend\n", StringComparison.Ordinal) < 0)
		{
			throw new InvalidOperationException("The UES1611 completion/damage lifecycle source drifted before race repair.");
		}
		return appendix.Replace("function EDAImportedAnimatedEnergyGenerator:SCO_BeginFaT1PowerOpening(generation)\n    if self.dead or self.tpId ~= \"ues1611\" then\n        return\n    end\n", "function EDAImportedAnimatedEnergyGenerator:SCO_BeginFaT1PowerOpening(generation)\n    if self.dead or self.tpId ~= \"ues1611\" or self.scoFaT1PowerLifecycleGeneration ~= generation then\n        return\n    end\n    self.scoFaT1PowerDamageRecoveryPending = false\n").Replace("    local generation = self.scoFaT1PowerLifecycleGeneration\n    self:SetRotatorsEnabled(false)\n", "    local generation = self.scoFaT1PowerLifecycleGeneration\n    self.scoFaT1PowerDamageRecoveryPending = true\n    self:SetRotatorsEnabled(false)\n").Replace("function EDAImportedAnimatedEnergyGenerator:OnStopBeingBuilt()\n    EDAEnergyGenerator.OnStopBeingBuilt(self)\n    if self.tpId == \"ues1611\" then\n        self.scoFaT1PowerLifecycleGeneration = (self.scoFaT1PowerLifecycleGeneration or 0) + 1\n        self:SCO_BeginFaT1PowerOpening(self.scoFaT1PowerLifecycleGeneration)\n    end\nend\n", "function EDAImportedAnimatedEnergyGenerator:OnStopBeingBuilt()\n    EDAEnergyGenerator.OnStopBeingBuilt(self)\n    if self.tpId ~= \"ues1611\" then\n        return\n    end\n    if self.scoFaT1PowerDamageRecoveryPending then\n        self:SetRotatorsEnabled(false)\n        return\n    end\n    self.scoFaT1PowerLifecycleGeneration = (self.scoFaT1PowerLifecycleGeneration or 0) + 1\n    self:SCO_BeginFaT1PowerOpening(self.scoFaT1PowerLifecycleGeneration)\nend\n");
	}

	public static void Apply()
	{
		List<CachedResource> list = new List<CachedResource>(PatchSpecs.Length);
		object obj = null;
		bool flag = false;
		try
		{
			obj = GetLuaFileCache();
			PatchSpec[] patchSpecs = PatchSpecs;
			foreach (PatchSpec patchSpec in patchSpecs)
			{
				if (!TryGetCachedResource(obj, patchSpec, out CachedResource resource))
				{
					if (!patchSpec.IsVirtual)
					{
						throw new FileNotFoundException("The required " + patchSpec.Description + " was not present in Sanctuary's Lua file cache.", patchSpec.RelativePath);
					}
					resource = new CachedResource(patchSpec, Path.GetFullPath(Path.Combine(Directory.GetCurrentDirectory(), patchSpec.RelativePath)), null);
					list.Add(resource);
				}
				else
				{
					list.Add(resource);
				}
			}
			int num = list.Count((CachedResource cachedResource) => ContainsOverride(cachedResource.Stock));
			if (num == list.Count)
			{
				Log("All eight EDA land-unit and three EDA power-generator overrides are already active.");
				return;
			}
			if (num != 0)
			{
				throw new InvalidOperationException("A partial EDA UEF land/power override was found. Refusing to mix patched and stock cached templates.");
			}
			if (list.Any((CachedResource cachedResource) => cachedResource.Spec.IsVirtual && cachedResource.Stock != null))
			{
				throw new InvalidOperationException("A reserved EDA UEF projectile route exists without this module's marker.");
			}
			Type nativeArrayType = list.Select((CachedResource cachedResource) => cachedResource.Stock?.GetType()).First((Type type) => (object)type != null);
			foreach (CachedResource item in list)
			{
				item.Replacement = (item.Spec.IsVirtual ? NativeArrayByteFactory.CreatePersistent(nativeArrayType, Array.Empty<byte>(), Encoding.UTF8.GetBytes(item.Spec.VirtualSource)) : AppendOverride(item.Stock, item.Spec.Appendix));
				if (!ContainsOverride(item.Replacement))
				{
					throw new InvalidOperationException("The replacement " + item.Spec.Description + " did not retain its override marker.");
				}
			}
			foreach (CachedResource item2 in list)
			{
				item2.ReplacementWasAssigned = true;
				SetCachedResource(obj, item2.Path, item2.Replacement);
			}
			flag = true;
			foreach (CachedResource item3 in list)
			{
				if (item3.Stock != null)
				{
					TryDisposeNativeArray(item3.Stock.GetType(), item3.Stock, "stock " + item3.Spec.Description);
				}
			}
			Log("Committed 8 source-gameplay UEF land units, 3 source-gameplay UEF power generators, 6 owned projectile routes, and 17 audited existing-port animation bundles.");
		}
		catch (Exception arg)
		{
			if (!flag && obj != null)
			{
				RollBackAndDispose(obj, list);
			}
			Log($"Failed to apply EDA UEF land/power resources: {arg}");
			throw;
		}
	}

