	private static PatchSpec Mobile(string targetId, string description, string sourceId, double collisionX, double collisionY, double collisionZ, double selectionX, double selectionZ, string animations, WeaponRig? weapon = null)
	{
		double value = collisionY / 2.0;
		string text = GameplayOverride(targetId);
		string text2 = weapon?.BuildLua(targetId) ?? string.Empty;
		string text3 = ((targetId == "uel1002") ? "UnitTemplate.additions.scoIdleResetLocomotion = true\n" : string.Empty);
		string appendix = "-- " + targetId + " is source-owned gameplay from " + sourceId + ".  The target keeps\n-- its EDA build-role and EDALandUnit inheritance; all FA-owned combat,\n-- economy, intel, movement, rack, and projectile fields are replaced.\n" + text + "\n" + text2 + "\nUnitTemplate.additions = UnitTemplate.additions or {}\n" + text3 + "UnitTemplate.additions.meshes = nil\nUnitTemplate.additions.rotators = nil\nUnitTemplate.movement = UnitTemplate.movement or {}\nUnitTemplate.movement.animClips = nil\nUnitTemplate.visuals = UnitTemplate.visuals or {}\nUnitTemplate.visuals.effectsPersistent = nil\nUnitTemplate.visuals.persistantEffects = nil\nUnitTemplate.visuals.effectsWhenActive = nil\nUnitTemplate.visuals.holes = nil\n\nUnitTemplate.collisionInfo = {\n    centerOffset = { x = 0, y = " + Lua(value) + ", z = 0 },\n    collisionSize = {\n        x = " + Lua(collisionX) + ",\n        y = " + Lua(collisionY) + ",\n        z = " + Lua(collisionZ) + ",\n    },\n}\nUnitTemplate.visuals.selection = UnitTemplate.visuals.selection or {}\nUnitTemplate.visuals.selection.size = {\n    x = " + Lua(selectionX) + ",\n    y = " + Lua(selectionZ) + ",\n}\nUnitTemplate.visuals.selection.offset = { x = 0, y = " + Lua(value) + ", z = 0 }\nUnitTemplate.additions.selectionHit = {\n    size = {\n        x = " + Lua(selectionX) + ",\n        y = " + Lua(selectionZ) + ",\n    },\n    offset = { x = 0, y = " + Lua(value) + ", z = 0 },\n}\n\n" + animations + "\n\nif UnitTemplate.visuals.effectsInstant then\n    for _, effects in pairs(UnitTemplate.visuals.effectsInstant) do\n        for _, effect in ipairs(effects) do\n            effect.boneName = \"Root\"\n        end\n    end\nend";
		return new PatchSpec(targetId, description, appendix, weapon);
	}

